class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        result = 1
        last = -1
        for i, v in enumerate(nums):
            if v == 1:
                if last != -1:
                    result = (result * (i - last)) % MOD
                last = i
        if last == -1:
            return 0
        return result
