import json
from hypothesis import strategies as st

MOD = 10**9 + 7

@st.composite
def gen(draw):
    n = draw(st.integers(1, 10))
    mode = draw(st.integers(0, 4))
    if mode == 0:
        # all zeros (answer 0)
        nums = [0] * n
    elif mode == 1:
        # all ones (answer 1)
        nums = [1] * n
    elif mode == 2:
        # exactly one 1 somewhere
        pos = draw(st.integers(0, n - 1))
        nums = [0] * n
        nums[pos] = 1
    else:
        nums = draw(st.lists(st.integers(0, 1), min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        a = json.loads(inp)
    except Exception:
        return False
    if not isinstance(a, list):
        return False
    if not (1 <= len(a) <= 10**5):
        return False
    return all(type(x) is int and x in (0, 1) for x in a)

def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    count = 0
    # Enumerate every set of cut positions among the n-1 gaps.
    for mask in range(1 << (n - 1) if n > 0 else 1):
        segments = []
        start = 0
        for g in range(n - 1):
            if mask >> g & 1:
                segments.append(nums[start:g + 1])
                start = g + 1
        segments.append(nums[start:])
        if all(sum(seg) == 1 for seg in segments):
            count += 1
    return json.dumps(count % MOD)
