    elif mode == 1:
        # all ones (answer 1 expected)
        nums = [1] * n
    elif mode == 2:
        # sparse ones
        nums = [0] * n
        k = draw(st.integers(0, n))
        for _ in range(k):
            nums[draw(st.integers(0, n - 1))] = 1
    else:
        nums = draw(st.lists(st.integers(0, 1), min_size=n, max_size=n))
    return json.dumps(nums)

