    return all(type(x) is int and x in (0, 1) for x in nums)

def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    count = 0
    # Enumerate every way to cut the array into contiguous non-empty parts.
    # Bit k of mask set => cut between index k and index k+1.
    for mask in range(1 << (n - 1)) if n > 1 else range(1):
        ok = True
        cur_ones = 0
        for i in range(n):
            cur_ones += nums[i]
            is_cut_after = (i < n - 1) and ((mask >> i) & 1)
            if i == n - 1 or is_cut_after:
                if cur_ones != 1:
                    ok = False
                    break
                cur_ones = 0
        if ok:
            count += 1
    return json.dumps(count % MOD)
