import json
from hypothesis import strategies as st

MOD = 10**9 + 7

@st.composite
def gen(draw):
    n = draw(st.one_of(
        st.integers(1, 3),
        st.integers(1, 10),
    ))
    mode = draw(st.integers(0, 4))
    if mode == 0:
        nums = [draw(st.integers(0, 1)) for _ in range(n)]
    elif mode == 1:
        nums = [0] * n
    elif mode == 2:
        nums = [1] * n
    elif mode == 3:
        nums = [0] * n
        pos = draw(st.lists(st.integers(0, n - 1), min_size=1, max_size=n))
        for p in pos:
            nums[p] = 1
    else:
        nums = [1 if i % 2 == 0 else 0 for i in range(n)]
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp.strip())
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    for x in nums:
        if type(x) is not int or x not in (0, 1):
            return False
    return True

def ref(inp):
    nums = json.loads(inp.strip())
    n = len(nums)
    count = 0
    # Enumerate every way to place cuts between consecutive elements.
    for mask in range(1 << (n - 1)):
        segments = []
        start = 0
        for i in range(n - 1):
            if (mask >> i) & 1:
                segments.append(nums[start:i + 1])
                start = i + 1
        segments.append(nums[start:])
        if all(sum(seg) == 1 for seg in segments):
            count += 1
    return str(count % MOD)
